def match(orders):
    buy_book = []  # List of (price, arrival_time, id, qty) - sorted by price desc, then arrival_time asc
    sell_book = []  # List of (price, arrival_time, id, qty) - sorted by price asc, then arrival_time asc
    trades = []
    order_map = {}  # Maps id to (side, index_in_book) for resting orders
    arrival_time = 0

    def add_to_book(side, price, id, qty):
        nonlocal arrival_time
        if side == 'buy':
            buy_book.append([price, arrival_time, id, qty])
            buy_book.sort(key=lambda x: (-x[0], x[1]))
        else:
            sell_book.append([price, arrival_time, id, qty])
            sell_book.sort(key=lambda x: (x[0], x[1]))
        order_map[id] = (side, None)  # Index will be set after sorting
        arrival_time += 1

    def update_order_map():
        order_map.clear()
        for i, order in enumerate(buy_book):
            order_map[order[2]] = ('buy', i)
        for i, order in enumerate(sell_book):
            order_map[order[2]] = ('sell', i)

    def match_order(side, price, id, qty, is_market):
        nonlocal arrival_time
        remaining_qty = qty

        if side == 'buy':
            # Match against sell book (lowest price first, then earliest arrival)
            i = 0
            while i < len(sell_book) and remaining_qty > 0:
                sell_price, sell_arrival, sell_id, sell_qty = sell_book[i]
                if is_market or sell_price <= price:
                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([id, sell_id, sell_price, trade_qty])
                    remaining_qty -= trade_qty
                    sell_book[i][3] -= trade_qty
                    if sell_book[i][3] == 0:
                        sell_book.pop(i)
                    else:
                        i += 1
                else:
                    break
        else:
            # Match against buy book (highest price first, then earliest arrival)
            i = 0
            while i < len(buy_book) and remaining_qty > 0:
                buy_price, buy_arrival, buy_id, buy_qty = buy_book[i]
                if is_market or buy_price >= price:
                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, id, buy_price, trade_qty])
                    remaining_qty -= trade_qty
                    buy_book[i][3] -= trade_qty
                    if buy_book[i][3] == 0:
                        buy_book.pop(i)
                    else:
                        i += 1
                else:
                    break

        # Add remaining quantity to the book (for limit and ioc orders)
        if remaining_qty > 0:
            add_to_book(side, price, id, remaining_qty)
        else:
            arrival_time += 1

    for order in orders:
        if order[0] == 'limit':
            _, id, side, price, qty = order
            match_order(side, price, id, qty, False)
        elif order[0] == 'ioc':
            _, id, side, price, qty = order
            match_order(side, price, id, qty, False)
        elif order[0] == 'market':
            _, id, side, qty = order
            match_order(side, None, id, qty, True)
        elif order[0] == 'cancel':
            _, id = order
            if id in order_map:
                side, idx = order_map[id]
                if side == 'buy':
                    buy_book[:] = [o for o in buy_book if o[2] != id]
                else:
                    sell_book[:] = [o for o in sell_book if o[2] != id]
                del order_map[id]

    return trades

